'use strict';
const $=s=>document.querySelector(s);
const P=globalThis.AtmosProgression;
const FAUNA={'Ásia':['Tigre','Panda','Pavão'],'África':['Leão','Elefante','Zebra'],'Europa':['Lobo','Raposa','Corvo'],'América do Norte':['Urso','Águia','Bisão'],'América do Sul':['Onça','Arara','Capivara'],'Oceania':['Canguru','Coala','Emu'],'Antártida':['Pinguim','Foca','Albatroz']};
const NATIONS=['Aurora','Obsidiana','Maré','Verdante'];
const KEY='nacoes-hibridas-v1';
let save={characters:[],active:0},storageOK=true;
try{const v=JSON.parse(localStorage.getItem(KEY));if(v&&Array.isArray(v.characters)&&v.characters.length<=10)save=v;}catch{storageOK=false;}
const valid=c=>c&&typeof c.name==='string'&&FAUNA[c.origin]?.includes(c.animal)&&Number.isFinite(c.hp)&&c.bag&&Object.values(c.bag).every(x=>Number.isInteger(x)&&x>=0)&&Number.isInteger(c.nation)&&c.nation>=0&&c.nation<4&&Number.isFinite(c.x)&&Number.isFinite(c.z);
save.characters=save.characters.filter(valid).map(P.prepare);save.active=Math.max(0,Math.min(save.characters.length-1,save.active|0));
let online=false,net=null,remotePlayers=[];
let player=save.characters[save.active]||null,logs=[],toastUntil=0,clock=0,raid=null,morphUntil=0,petTime=0,target=null,lastAttack=0,weatherIndex=0;
const weather=[{name:'Névoa primordial',friction:.75,fog:.13},{name:'Aurora dos primeiros deuses',friction:.85,fog:.07},{name:'Chuva da primeira era',friction:.55,fog:.05}];
const canvas=$('#world'),ctx=canvas.getContext('2d');let width=800,height=800,dpr=1,scale=25;
const keys=new Set(),resources=[],enemies=[];
let madregona=player?.madregona||null;
const dialogOpen=()=>['#creator','#info','#login','#codex','#soundtrack','#chronicles','#characterSheet'].some(id=>$(id).open);
let seed=93127;function random(){seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;}
for(let i=0;i<64;i++)resources.push({x:random()*26-13,z:random()*26-13,type:['fruit','plant','liquid','coin'][i%4],ready:0});
for(let i=0;i<8;i++)enemies.push({x:random()*22-11,z:5+random()*7,hp:60,ready:0});
const trees=Array.from({length:47},()=>({x:random()*30-15,z:random()*30-15,size:1+random()*1.5,color:random()>.45?'#779e9c':'#9b83b4'}));
function persist(){if(online)return;try{localStorage.setItem(KEY,JSON.stringify(save));}catch{storageOK=false;notice('Armazenamento indisponível: progresso apenas nesta sessão.');}}
function notice(message){$('#toast').textContent=message;$('#toast').classList.add('visible');toastUntil=performance.now()+3500;logs.unshift(message);logs=logs.slice(0,5);$('#log').replaceChildren(...logs.map(x=>{const n=document.createElement('li');n.textContent=x;return n;}));}
function bag(){return player?.bag||{fruit:0,plant:0,liquid:0,coin:0,potion:0,cloth:0};}
function ui(){const b=bag();$('#slots').textContent=online?'ONLINE':save.characters.length+'/10';$('#playerName').textContent=player?.name||'Um sopro à espera';$('#dna').textContent=player?player.animal+' · '+player.origin:'Escolha sua origem para começar.';$('#continent').textContent=player?.origin||'América do Sul';$('#nation').textContent=player?(player.customNation&&(/^([0-6])-([0-3])$/.test(player.customNation)?NATIONS[Number(player.customNation.split('-')[1])]:player.customNation))||NATIONS[player.nation]:'Aurora';$('#nationText').textContent=online?'Estado sincronizado com o servidor.':player?.blocked?.length?'Territórios perdidos: '+player.blocked.map(i=>NATIONS[i]).join(', '):'Seu território de origem. Construa sua história.';$('#hpbar').style.width=Math.max(0,Math.min(100,(player?.hp??100)/P.maxHP(player)*100))+'%';$('#hp').textContent=Math.ceil(player?.hp??100)+' / '+P.maxHP(player)+' · Vitalidade';$('#inventory').replaceChildren(...Object.entries({fruit:'◉ Frutas',plant:'♧ Plantas',liquid:'◈ Líquidos',coin:'◎ Moedas',potion:'✧ Poções',cloth:'▧ Tecidos'}).map(([key,label])=>{const n=document.createElement('div');n.className='resource';n.textContent=label;const v=document.createElement('b');v.textContent=b[key]||0;n.append(v);return n;}));journeyUI();$('#boss').textContent=raid?'Guardião · '+Math.max(0,Math.ceil((raid.ends-clock)))+'s restantes':player?.cards?'Carta Asa Prismática conquistada.':'Um guardião antigo aguarda na fronteira.';$('#bossHp').value=raid?.hp??250;$('#raid').disabled=!!raid||!player;$('#morph').disabled=!player?.cards;$('#potion').disabled=!b.potion||!player||player.hp>=P.maxHP(player);$('#craft').disabled=!player||b.fruit<2||b.liquid<1;$('#petTitle').textContent=player?.pet?'Espírito · '+player.pet:'Espírito da floresta';document.querySelectorAll('[data-pet]').forEach(n=>{n.classList.toggle('active',n.dataset.pet===player?.pet);n.setAttribute('aria-pressed',String(n.dataset.pet===player?.pet));});$('#petText').textContent=online?'No online, Luta aumenta seu dano. Coleta e cura automáticas ainda estão disponíveis apenas no solo.':'Magia restaura vida; luta aumenta seu dano; trabalho coleta recursos próximos.';$('#collect').disabled=!player;$('#attack').disabled=!player;$('#createNation').disabled=online||!player||b.coin<10;$('.health').setAttribute('aria-valuenow',String(Math.max(0,Math.min(P.maxHP(player),player?.hp??100))));$('.health').setAttribute('aria-valuemax',String(P.maxHP(player)));if(typeof characterUI==='function')characterUI();}

const ORIGIN_LORE={'Ásia':'Entre montanhas e antigas florestas, GAYA despertou a força e a contemplação.','África':'Sob o primeiro sol, a vida aprendeu a caminhar com coragem.','Europa':'Nas matas de névoa, o instinto encontrou a memória da criação.','América do Norte':'Entre céus abertos e grandes planícies, nasceu o chamado da liberdade.','América do Sul':'Sob raízes profundas e rios vivos, o primeiro sopro ainda ecoa.','Oceania':'Nas terras cercadas de água, a vida descobriu caminhos singulares.','Antártida':'No silêncio do gelo, GAYA guardou a resistência dos primeiros viventes.'};
let journeySignature='';
function journeyUI(){
const count=Math.min(5,Math.max(0,player?.collected||0)),crafted=(player?.crafted||0)>0,won=(player?.cards||0)>0;
const steps=[['Reunir as dádivas',count>=5,count+'/5 recursos · aproxime-se dos cristais'],['Cultivar a vida',crafted,'Prepare uma poção · 2 frutas + 1 líquido'],['Enfrentar o guardião',won,'Vença a raide · receba a Asa Prismática']];
const completed=steps.filter(s=>s[1]).length;const signature=JSON.stringify([count,crafted,won,online,!!player,!!raid]);if(signature===journeySignature)return;journeySignature=signature;
$('#journeyCount').textContent=completed+'/3';$('#journeyProgress').value=completed;$('#journeyTitle').textContent=['Centelha de GAYA','Guardião da semente','Tecelão da vida','Herdeiro do Primeiro Sopro'][completed];$('#journeyNote').textContent=online?'Marcos visuais desta sessão · sem bônus de combate.':'Marcos salvos com seu vivente · sem bônus de combate.';
$('#quests').replaceChildren(...steps.map(([text,done,detail],i)=>{const row=document.createElement('div');row.className='quest'+(done?' done':'');const mark=document.createElement('span');mark.className='quest-mark';mark.textContent=done?'✓':String(i+1);const label=document.createElement('div');label.textContent=text;const hint=document.createElement('small');hint.textContent=detail;label.append(hint);row.append(mark,label);return row;}));
$('#nextStep').textContent=!player?'Crie um vivente para iniciar sua história.':raid?'O prisma está na fronteira (x: 0, z: 7). Aproxime-se e ataque.':!steps[0][1]?'Toque no chão para caminhar. Aproxime-se dos cristais e colete 5 recursos.':!crafted?'Reúna 2 frutas e 1 líquido. Prepare uma poção em Dádivas da Terra.':!won?'Prepare poções, escolha Luta e inicie a raide quando estiver pronto.':'A Asa Prismática é sua. Use Ascender para se transformar por 15 segundos.';
}
$('#codexButton').onclick=()=>$('#codex').showModal();
$('#focusMap').onclick=()=>{const focused=document.body.classList.toggle('map-focused');$('#focusMap').setAttribute('aria-pressed',String(focused));$('#focusMap').setAttribute('aria-label',focused?'Restaurar painéis':'Ampliar mapa');resize();};
const ANIMAL_LORE={'Tigre':'A presença silenciosa entre as primeiras florestas.','Panda':'A calma que encontra abrigo no mundo recém-nascido.','Pavão':'As cores com que a criação aprendeu a se mostrar.','Leão':'A coragem de caminhar sob o primeiro sol.','Elefante':'A memória viva dos caminhos da terra.','Zebra':'Cada marca, uma história que só você carrega.','Lobo':'O chamado de pertencer sem perder o próprio caminho.','Raposa':'A curiosidade diante de um mundo ainda sem respostas.','Corvo':'Os olhos atentos entre a névoa e o desconhecido.','Urso':'A força serena de quem guarda seu lugar no mundo.','Águia':'O horizonte como convite para seguir adiante.','Bisão':'Raízes firmes sob a vastidão dos primeiros céus.','Onça':'O mistério vivo entre as raízes de GAYA.','Arara':'A voz colorida de uma floresta que acaba de despertar.','Capivara':'A vida que floresce no encontro com outros viventes.','Canguru':'O impulso de atravessar caminhos ainda por nascer.','Coala':'O tempo de escutar o mundo entre as folhas.','Emu':'O caminho se revela a cada passo.','Pinguim':'O calor dos vínculos em um mundo de silêncio.','Foca':'O encontro entre dois mundos: a água e a terra.','Albatroz':'A distância como promessa de novas histórias.'};
function animalStory(){const animal=$('#animal').value;$('#animalNote').textContent=animal?animal+' · '+(ANIMAL_LORE[animal]||'Uma nova centelha no mundo de GAYA.'):'';}
function updateAnimals(){const origin=$('#origin').value;$('#animal').replaceChildren(...FAUNA[origin].map(a=>new Option(a,a)));$('#originNote').textContent=ORIGIN_LORE[origin]||'Sua herança desperta neste continente.';animalStory();}
$('#origin').replaceChildren(...Object.keys(FAUNA).map(a=>new Option(a,a)));$('#origin').value='América do Sul';updateAnimals();$('#origin').onchange=updateAnimals;$('#animal').onchange=animalStory;
function creator(){$('#creatorMode').textContent=online?'SUA JORNADA ONLINE':'SUA JORNADA SOLO';if(online){net.chooseCharacter();return;}const r=$('#roster');r.replaceChildren(...save.characters.map((c,i)=>{const n=document.createElement('button');n.type='button';n.textContent=c.name+' · '+c.animal+' · '+c.origin;n.onclick=()=>{if(raid){notice('Finalize a raide antes de trocar.');return;}player=c;madregona=player.madregona||null;save.active=i;morphUntil=0;target=null;$('#creator').close();persist();ui();};return n;}));$('#form .primary').disabled=save.characters.length>=10;$('#closeCreator').hidden=!player;$('#creator').showModal();}
$('#characters').onclick=creator;$('#closeCreator').onclick=()=>$('#creator').close();$('#creator').addEventListener('cancel',e=>{if(!player)e.preventDefault();});
$('#form').onsubmit=e=>{e.preventDefault();if(online){net.createCharacter(new FormData(e.target));return;}if(save.characters.length>=10)return;const data=new FormData(e.target),name=String(data.get('name')).trim(),origin=String(data.get('origin')),animal=String(data.get('animal'));if(!name||!FAUNA[origin]?.includes(animal))return;player={name,origin,animal,hp:100,x:0,z:-2,nation:0,blocked:[],bag:{fruit:0,plant:0,liquid:0,coin:0,potion:0,cloth:0},collected:0,crafted:0,cards:0,pet:'magia'};P.prepare(player);madregona=null;save.characters.push(player);save.active=save.characters.length-1;$('#creator').close();persist();ui();notice('GAYA lhe deu a centelha, '+name+'. Reúna as primeiras dádivas da terra.');};
$('#help').onclick=()=>$('#info').showModal();
$('#craft').onclick=()=>{if(online){net.intent({type:'craft'});return;}const b=bag();if(!player||b.fruit<2||b.liquid<1)return;b.fruit-=2;b.liquid--;b.potion++;player.crafted++;gainXP(8);persist();ui();notice('Poção vital criada.');};
$('#potion').onclick=()=>{if(online){net.intent({type:'potion'});return;}if(!player||!bag().potion)return;if(player.hp>=P.maxHP(player)){notice('Sua vitalidade já está completa.');return;}player.bag.potion--;player.hp=Math.min(P.maxHP(player),player.hp+45);persist();ui();notice('Vitalidade recuperada.');};
$('#createNation').onclick=()=>{if(online){notice('Fundação online ainda não habilitada.');return;}if(!player)return;if(bag().coin<10){notice('Você precisa de 10 moedas para fundar uma comunidade.');return;}const name=prompt('Nome da comunidade (até 24 caracteres):');if(!name?.trim())return;player.customNation=name.trim().slice(0,24);player.bag.coin-=10;persist();ui();notice('Comunidade fundada nesta jornada solo.');};
document.querySelectorAll('[data-pet]').forEach(n=>n.onclick=()=>{if(!player)return;if(online){net.intent({type:'pet',mode:n.dataset.pet});return;}player.pet=n.dataset.pet;persist();ui();notice('Companheiro em modo '+player.pet+'.');});
const distance=(a,b)=>Math.hypot(a.x-b.x,a.z-b.z);
function collect(silent=false){if(!player)return;if(online){net.collect();return;}const r=resources.filter(r=>r.ready<=clock&&distance(player,r)<2.5).sort((a,b)=>distance(player,a)-distance(player,b))[0];if(!r){if(!silent)notice('Aproxime-se de um recurso brilhante para coletar.');return;}r.ready=clock+25;player.bag[r.type]++;player.collected++;gainXP(4);if(player.collected%5===0)player.bag.cloth++;persist();ui();if(!silent)notice('Recurso coletado.'+(player.collected%5===0?' Fibras refinadas em tecido.':''));}
$('#collect').onclick=()=>collect();
function death(){const old=player.nation;const options=[0,1,2,3].filter(n=>n!==old);player.nation=options[Math.floor(Math.random()*options.length)];player.blocked=[...new Set([...(player.blocked||[]),old])];player.blocked=player.blocked.filter(n=>n!==player.nation);delete player.customNation;player.hp=P.maxHP(player);player.energy=P.maxEnergy(player);player.energy_updated=gameNow();player.active_form='origin';player.disguise_animal='';player.veil_until=0;if(madregona?.hp>0){madregona.hp=180;madregona.revealed=0;madregona.last_pulse=gameNow();}player.x=0;player.z=-3;target=null;raid=null;morphUntil=0;persist();ui();notice('Você caiu. Sua antiga afiliação foi removida. Renascimento em '+NATIONS[player.nation]+'.');}
function attack(){if(!player)return;if(online){net.attack();return;}if(!player||clock-lastAttack<.5)return;lastAttack=clock;const damage=(morphUntil>clock?40:20)+(player.pet==='luta'?10:0)+P.integer(player.power)*2;if(madregona?.hp>0&&distance(player,madregona)<=3&&player.z>4){hitSoloMadregona(damage);persist();ui();return;}if(raid&&distance(player,raid)<3){raid.hp-=damage;if(raid.hp<=0){raid=null;player.cards++;player.bag.coin+=10;gainXP(150);persist();notice('Guardião derrotado! Carta Asa Prismática e 10 moedas recebidas.');}ui();return;}const enemy=enemies.find(e=>e.hp>0&&e.ready<=clock&&distance(player,e)<2.5);if(!enemy){notice('Nenhum inimigo ao alcance. Procure a fronteira.');return;}enemy.hp-=damage;if(enemy.hp<=0){enemy.ready=clock+20;player.bag.coin+=2;gainXP(20);notice('Criatura derrotada. +2 moedas.');persist();ui();}}
$('#attack').onclick=attack;$('#raid').onclick=()=>{if(online){net.intent({type:'raid'});return;}if(!player||raid)return;raid={x:0,z:7,hp:250,ends:clock+90};notice('Raide iniciada! Vá até o prisma no norte da fronteira. Você tem 90 segundos.');ui();};
$('#morph').onclick=()=>{if(online){net.intent({type:'morph'});return;}if(!player?.cards)return;if(morphUntil>clock){notice('Transformação já ativa.');return;}morphUntil=clock+15;notice('Asa Prismática ativa por 15 segundos: dano e velocidade ampliados.');};
function projection(x,y,z){return{x:width/2+(x-z)*scale,y:height*.53+(x+z)*scale*.47-y*scale};}
function poly(points,fill,stroke){ctx.beginPath();points.forEach((p,i)=>{const v=projection(...p);i?ctx.lineTo(v.x,v.y):ctx.moveTo(v.x,v.y);});ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.stroke();}}
function prism(x,z,w,h,color){poly([[x-w,0,z+w],[x+w,0,z+w],[x+w,h,z+w],[x-w,h,z+w]],color);poly([[x+w,0,z-w],[x+w,0,z+w],[x+w,h,z+w],[x+w,h,z-w]],'#294f54');poly([[x-w,h,z-w],[x+w,h,z-w],[x+w,h,z+w],[x-w,h,z+w]],'#b5c8b8');}
function orb(x,y,z,r,color){const p=projection(x,y,z);ctx.beginPath();ctx.ellipse(p.x,p.y,r*scale,r*scale,0,0,Math.PI*2);ctx.fillStyle=color;ctx.fill();}
function drawTree(t){const p=projection(t.x,0,t.z);ctx.fillStyle='#0b252b55';ctx.beginPath();ctx.ellipse(p.x+8,p.y+4,20,8,0,0,7);ctx.fill();prism(t.x,t.z,.1,t.size,'#5d716d');for(let i=0;i<3;i++){const h=t.size+.4+i*.35,w=(3-i)*.31;poly([[t.x-w,h,t.z],[t.x,h+.8,t.z],[t.x+w,h,t.z],[t.x,h-.5,t.z+w]],t.color);}orb(t.x,t.size+1,t.z,.065,'#c3ebc5');}
function drawMadregona(){const e=madregona,color=e.revealed?'#74588f':'#d8d5bb';prism(e.x,e.z,.24,.9,color);orb(e.x,1.18,e.z,.25,e.revealed?'#493856':'#c29b7b');if(e.revealed){for(let i=0;i<4;i++){const a=clock+i*Math.PI/2;orb(e.x+Math.cos(a)*.8,1.1+Math.sin(a*2)*.3,e.z+Math.sin(a)*.8,.13,'#b48bdf');}}else if(/Arara|Pavão|Águia|Corvo|Albatroz|Emu|Pinguim/.test(e.disguise_animal)){poly([[e.x,.8,e.z],[e.x-1,1.1,e.z],[e.x-.3,.3,e.z]],'#a6c8b2');poly([[e.x,.8,e.z],[e.x+1,1.1,e.z],[e.x+.3,.3,e.z]],'#b8a5cb');}else{orb(e.x-.18,1.4,e.z,.12,'#d4bf9c');orb(e.x+.18,1.4,e.z,.12,'#d4bf9c');}const label=projection(e.x,2.3,e.z);ctx.font='11px sans-serif';ctx.textAlign='center';ctx.fillStyle='#e8d5fa';ctx.fillText(e.revealed?'Madregona · '+e.hp+'/180':'Errante · '+e.disguise_animal,label.x,label.y);}
function render(){ctx.clearRect(0,0,width,height);const bg=ctx.createLinearGradient(0,0,0,height);bg.addColorStop(0,'#20363c');bg.addColorStop(1,'#395455');ctx.fillStyle=bg;ctx.fillRect(0,0,width,height);for(let z=-16;z<16;z++)for(let x=-16;x<16;x++){const wave=Math.sin(x*.6+z*.3)*.08;poly([[x,wave,z],[x+1,wave,z],[x+1,wave,z+1],[x,wave,z+1]],z>4?((x+z)%2?'#465454':'#485757'):((x+z)%2?'#4c7167':'#50766b'),'#7ea38b0c');}poly([[-16,.05,4],[16,.05,4],[16,.05,4.1],[-16,.05,4.1]],'#ca9f8c77');for(let i=-15;i<15;i++){poly([[i,.12,-4],[i+1,.12,-4],[i+1,.12,-3],[i,.12,-3]],'#9aaa8c88');}prism(-5,-5,1.2,1.1,'#6f8780');poly([[-6.6,1.1,-6.6],[-3.4,1.1,-6.6],[-5,2.7,-5]],'#d2bdb0');prism(6,-7,.8,1.5,'#648379');
const objects=trees.map(t=>({depth:t.x+t.z,draw:()=>drawTree(t)}));objects.push({depth:-10,draw:()=>{const x=-5,z=-5;for(let i=0;i<12;i++){const a=i*Math.PI/6;orb(x+Math.cos(a)*2,.15,z+Math.sin(a)*2,.08,'#ddc795');}prism(x,z,.28,2.8,'#a38d62');for(let i=0;i<7;i++){const a=i*Math.PI*2/7,tx=x+Math.cos(a)*1.15,tz=z+Math.sin(a)*1.15;drawTree({x:tx,z:tz,size:2.5+Math.sin(i)*.5,color:i%2?'#b9cf99':'#d4c08b'});}orb(x,4.6+Math.sin(clock)*.1,z,.22,'#f4dfaa');const p=projection(x,5.3,z);ctx.font='10px serif';ctx.textAlign='center';ctx.fillStyle='#f4dfaa';ctx.fillText('PRIMEIRA RAIZ',p.x,p.y);}});for(const r of resources){if(r.ready>clock)continue;objects.push({depth:r.x+r.z,draw:()=>{const color={fruit:'#e8acb2',plant:'#c3ef93',liquid:'#9edee8',coin:'#f2d796'}[r.type];orb(r.x,.35+Math.sin(clock*2+r.x)*.12,r.z,.16,color);const p=projection(r.x,0,r.z);ctx.strokeStyle=color+'55';ctx.beginPath();ctx.ellipse(p.x,p.y,9,4,0,0,7);ctx.stroke();}});}for(const e of (online?[]:enemies)){if(e.ready>clock)continue;objects.push({depth:e.x+e.z,draw:()=>{prism(e.x,e.z,.28,.5,'#b9858e');orb(e.x,.8,e.z,.27,'#d3a2a2');}});}if(madregona?.hp>0)objects.push({depth:madregona.x+madregona.z,draw:drawMadregona});if(raid)objects.push({depth:7,draw:()=>{const p=projection(0,2+Math.sin(clock)*.2,7);ctx.save();ctx.translate(p.x,p.y);ctx.rotate(clock*.25);ctx.fillStyle='#c7a7f5';ctx.shadowBlur=30;ctx.shadowColor='#c7a7f5';ctx.fillRect(-22,-22,44,44);ctx.restore();}});if(player)objects.push({depth:player.x+player.z,draw:()=>{const p=player;const m=morphUntil>clock;const shadow=p.active_form==='madregona'&&!p.disguise_animal;const shownAnimal=p.disguise_animal||p.animal;const pos=projection(p.x,0,p.z);ctx.fillStyle='#142b3255';ctx.beginPath();ctx.ellipse(pos.x,pos.y,15,6,0,0,7);ctx.fill();prism(p.x,p.z,.22,.8,shadow?'#73558c':m?'#c5a6e6':'#e4e6c8');orb(p.x,1.1,p.z,.24,'#c29b7b');if(/Arara|Pavão|Águia|Corvo|Albatroz|Emu|Pinguim/.test(shownAnimal)||m){poly([[p.x,.8,p.z],[p.x-1.1,1.2,p.z],[p.x-.4,.3,p.z]],'#a4d5c1');poly([[p.x,.8,p.z],[p.x+1.1,1.2,p.z],[p.x+.4,.3,p.z]],'#b9a6d5');}else{orb(p.x-.18,1.35,p.z,.12,'#d4bf9c');orb(p.x+.18,1.35,p.z,.12,'#d4bf9c');}orb(p.x+.8,.65+Math.sin(clock*3)*.2,p.z+.4,.2,'#c7dafa');ctx.font='11px sans-serif';ctx.textAlign='center';ctx.fillStyle='#eff8ed';ctx.fillText(p.name,pos.x,pos.y-52);}});for(const other of remotePlayers){objects.push({depth:other.x+other.z,draw:()=>{prism(other.x,other.z,.22,.8,'#c49da9');orb(other.x,1.1,other.z,.24,'#c29b7b');const p=projection(other.x,1.7,other.z);ctx.font='11px sans-serif';ctx.textAlign='center';ctx.fillStyle='#fff';ctx.fillText(other.name,p.x,p.y);}});}objects.sort((a,b)=>a.depth-b.depth).forEach(o=>o.draw());const fog=weather[weatherIndex].fog;ctx.fillStyle='rgba(172,207,198,'+fog+')';ctx.fillRect(0,0,width,height);for(let i=0;i<28;i++){const x=(i*113+clock*12)%width,y=(i*73+Math.sin(clock+i)*20)%height;ctx.fillStyle=weatherIndex===1?'#d2b9f799':'#c4ecc44a';ctx.beginPath();ctx.arc(x,y,1.5,0,7);ctx.fill();}if(weatherIndex===2){ctx.strokeStyle='#d3e9ac38';for(let i=0;i<55;i++){const x=(i*137+clock*23)%width,y=(i*83+clock*160)%height;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x-4,y+12);ctx.stroke();}}}
function resize(){const r=canvas.getBoundingClientRect();width=r.width;height=r.height;dpr=Math.min(devicePixelRatio||1,2);canvas.width=width*dpr;canvas.height=height*dpr;ctx.setTransform(dpr,0,0,dpr,0,0);scale=Math.max(13,Math.min(width/31,height/27));}new ResizeObserver(resize).observe(canvas);
canvas.addEventListener('pointerdown',e=>{if(!player)return;const r=canvas.getBoundingClientRect(),a=(e.clientX-r.left-width/2)/scale,b=(e.clientY-r.top-height*.53)/(scale*.47);target={x:Math.max(-13,Math.min(13,(a+b)/2)),z:Math.max(-13,Math.min(13,(b-a)/2))};});
addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea,button,a,[contenteditable=true]')||dialogOpen())return;const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();keys.add(k);if(!e.repeat){if(k==='e')collect();if(k===' ')attack();if(k==='q')useSkill(1);if(k==='r')useSkill(2);}});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));addEventListener('blur',()=>keys.clear());
let prev=performance.now(),lastUI=0,lastSave=0;function frame(now){const dt=Math.min((now-prev)/1000,.06);prev=now;if(!document.hidden){clock+=dt;if(player&&!dialogOpen()){let dx=Number(keys.has('d')||keys.has('arrowright'))-Number(keys.has('a')||keys.has('arrowleft')),dz=Number(keys.has('s')||keys.has('arrowdown'))-Number(keys.has('w')||keys.has('arrowup'));if(dx||dz)target=null;else if(target){const d=distance(player,target);if(d>.15){dx=(target.x-player.x)/d;dz=(target.z-player.z)/d;}else target=null;}const length=Math.hypot(dx,dz)||1,speed=3.3*weather[weatherIndex].friction*(morphUntil>clock?1.65:1);if(online){net.move(dx/length,dz/length);}else{player.x=Math.max(-13,Math.min(13,player.x+dx/length*speed*dt));player.z=Math.max(-13,Math.min(13,player.z+dz/length*speed*dt));for(const e of enemies){if(e.ready<=clock&&e.hp<=0)e.hp=60;if(e.ready<=clock&&distance(player,e)<1.5&&player.z>4)player.hp-=7*dt*(player.veil_until>gameNow()?0.5:1);}if(raid){if(clock>=raid.ends){raid=null;notice('O guardião recuou. Você pode tentar novamente.');}else if(distance(player,raid)<3)player.hp-=9*dt*(player.veil_until>gameNow()?0.5:1);}soloShadowPulse();if(player.hp<=0)death();petTime+=dt;if(petTime>5){petTime=0;if(player.pet==='trabalho')collect(true);if(player.pet==='magia')player.hp=Math.min(P.maxHP(player),player.hp+4);}const w=Math.floor(clock/40)%3;if(w!==weatherIndex){weatherIndex=w;notice('O clima mudou: '+weather[w].name+'.');}}$('#zone').textContent=player.z>4?'FRONTEIRA HOSTIL':'SANTUÁRIO';$('#zone').style.color=player.z>4?'#efb8aa':'#b9f3b0';if(clock-lastSave>5){lastSave=clock;persist();}}if(clock-lastUI>.3){lastUI=clock;ui();$('#weather').textContent=weather[weatherIndex].name+' · '+(weather[weatherIndex].friction<.6?'Passos lentos':'Caminho vivo');$('#day').textContent='CICLO '+String(1+Math.floor(clock/120)).padStart(2,'0');}render();}if(now>toastUntil)$('#toast').classList.remove('visible');requestAnimationFrame(frame);}document.addEventListener('visibilitychange',()=>{keys.clear();if(document.hidden)persist();prev=performance.now();});function startGame(){prev=performance.now();ui();resize();requestAnimationFrame(frame);if(!player)creator();if(!storageOK)notice('Dados locais indisponíveis. O progresso dura apenas esta sessão.');}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',startGame,{once:true});else startGame();
